 __device__ inline uint16_t rbf(float value) { return float_to_bf16_bits(value); }

+// Two CFG rows share weight loads. Four virtual lanes per physical thread
+// preserve dense_gemv_out_kernel's 256-thread FMA partitions and reduction tree.
+__global__ __launch_bounds__(64) void vv_diff_cfg_linear_kernel(
+    const uint16_t* __restrict__ x, const uint16_t* __restrict__ w,
+    uint16_t* __restrict__ out, int64_t k, int64_t n) {
+  const int tid = threadIdx.x;
+  const int64_t col = blockIdx.x;
+  const int64_t main_end = (k / 2048) * 2048;
+  float a[4][2] = {};
+  // Interleave the four independent accumulators to hide FMA latency without
+  // changing the order of operations within any virtual lane.
+  for (int64_t base = tid * 8; base < main_end; base += 2048) {
+#pragma unroll
+    for (int j = 0; j < 8; ++j) {
+#pragma unroll
+      for (int part = 0; part < 4; ++part) {
+        const int64_t index = base + part * 512 + j;
+        const float weight = bf16_bits_to_float(w[col * k + index]);
+        a[part][0] = fmaf(bf16_bits_to_float(x[index]), weight, a[part][0]);
+        a[part][1] = fmaf(bf16_bits_to_float(x[k + index]), weight, a[part][1]);
+      }
+    }
+  }
+  for (int64_t base = main_end + tid; base < k; base += 256) {
+#pragma unroll
+    for (int part = 0; part < 4; ++part) {
+      const int64_t index = base + part * 64;
+      if (index < k) {
+        const float weight = bf16_bits_to_float(w[col * k + index]);
+        a[part][0] = fmaf(bf16_bits_to_float(x[index]), weight, a[part][0]);
+        a[part][1] = fmaf(bf16_bits_to_float(x[k + index]), weight, a[part][1]);
+      }
+    }
+  }
+  __shared__ float partial[2][64];
+#pragma unroll
+  for (int row = 0; row < 2; ++row) {
+    // Original s=128, then s=64 additions, before the cross-wave s=32.
+    partial[row][tid] = (a[0][row] + a[2][row]) + (a[1][row] + a[3][row]);
+  }
+  __syncthreads();
+  if (tid < 32) {
+#pragma unroll
+    for (int row = 0; row < 2; ++row) {
+      float sum = partial[row][tid] + partial[row][tid + 32];
+      for (int offset = 16; offset > 0; offset >>= 1) {
+        sum += __shfl_down(sum, offset);
+      }
+      if (tid == 0) out[row * n + col] = rbf(sum);
+    }
+  }
+}
+
 constexpr int VV_DIFF_WARPS = 8;  // 256 threads, warp-per-row

 __global__ void vv_diff_rmsnorm_kernel(
@@ -303,3 +356,12 @@ extern "C" int hipengine_vv_diff_cfg_combine_bf16(
                      0, stream, c, u, cfg, out, n);
   return static_cast<int>(hipGetLastError());
 }
+
+extern "C" int hipengine_vv_diff_cfg_linear_bf16(
+    const uint16_t* x, const uint16_t* w, uint16_t* out,
+    int64_t rows, int64_t k, int64_t n, hipStream_t stream) {
+  if (rows != 2 || k <= 0 || n <= 0) return static_cast<int>(hipErrorInvalidValue);
+  hipLaunchKernelGGL(vv_diff_cfg_linear_kernel, dim3(static_cast<unsigned>(n)),
+                    dim3(64), 0, stream, x, w, out, k, n);
+  return static_cast<int>(hipGetLastError());
+}
